import { z } from 'zod'
import { CATEGORY_COLORS } from '@/constants/category-colors.constants'
import { CATEGORY_KINDS } from '../utils/categories.utils'

/** a row of public.categories as the client inserts it; depth is generated by the DB, two levels at most (23503) */
export const createCategoryInputSchema = z.object({
  id: z.uuid(),
  ledger_id: z.uuid(),
  kind: z.enum(CATEGORY_KINDS),
  parent_id: z.uuid().nullable(),
  name: z.string().trim().min(1).max(80),
  color: z.enum(CATEGORY_COLORS).nullable(),
  icon: z.string().max(40).nullable(),
  sort_order: z.int(),
})

export type CreateCategoryInput = z.infer<typeof createCategoryInputSchema>

/** an update carries the version it was made from; kind and parent do not change after creation */
export const updateCategoryInputSchema = z.object({
  id: z.uuid(),
  expectedVersion: z.int().positive(),
  patch: z
    .object({
      name: z.string().trim().min(1).max(80),
      color: z.enum(CATEGORY_COLORS).nullable(),
      icon: z.string().max(40).nullable(),
      sort_order: z.int(),
      // restoring from the archive; archiving itself goes through archive_category
      archived_at: z.null(),
    })
    .partial(),
})

export type UpdateCategoryInput = z.infer<typeof updateCategoryInputSchema>
